// app/manage/page.tsx
"use client";

import { useState, useCallback, useEffect } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Spinner } from "@/components/ui/spinner";
import {
  getFeedUrlFromHtml,
  fetchAndParseRSS,
  loadFeedsFromStorage,
  saveFeedToStorage,
  type FeedData,
} from "@/lib/rssUtils";
import { suggestFeedsWithWorker } from "@/lib/useTransformerWorker";

// Suggested Feed component to reduce re-renders
const SuggestedFeed = ({ feed, onSubscribe }: { feed: FeedData, onSubscribe: (feed: FeedData) => void }) => {
  return (
    <Card key={feed.url} className="shadow-sm">
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <img
              src={`https://www.google.com/s2/favicons?sz=32&domain_url=${feed.url}`}
              className="w-6 h-6"
              alt="favicon"
            />
            <div>
              <p className="font-medium text-[var(--text-primary)]">{feed.title}</p>
              <p className="text-xs text-[var(--text-secondary)]">{feed.url}</p>
            </div>
          </div>
          <Button 
            variant="default" 
            className="text-sm py-1 px-3"
            onClick={() => onSubscribe(feed)}
          >
            Subscribe
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

export default function ManagePage() {
  const [feedUrlInput, setFeedUrlInput] = useState("");
  const [topic, setTopic] = useState("");
  const [suggestedFeeds, setSuggestedFeeds] = useState<FeedData[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [savedFeeds, setSavedFeeds] = useState<FeedData[]>([]);

  // Load saved feeds on initial render
  useEffect(() => {
    const feeds = loadFeedsFromStorage();
    setSavedFeeds(feeds);
  }, []);

  // Handle adding a new feed
  const handleAddFeed = useCallback(async () => {
    if (!feedUrlInput.trim()) return;
    
    setIsLoading(true);
    try {
      const resolvedFeedUrl = await getFeedUrlFromHtml(feedUrlInput);
      if (resolvedFeedUrl) {
        const feedData = await fetchAndParseRSS(resolvedFeedUrl);
        if (feedData) {
          saveFeedToStorage({ title: feedData.title, url: resolvedFeedUrl });
          setFeedUrlInput(""); // Clear input after successful add
          
          // Update saved feeds list
          const feeds = loadFeedsFromStorage();
          setSavedFeeds(feeds);
        }
      }
    } catch (error) {
      console.error("Error adding feed:", error);
    } finally {
      setIsLoading(false);
    }
  }, [feedUrlInput]);

  // Handle topic suggestion
  const handleTopicSuggest = useCallback(async () => {
    if (!topic.trim()) return;
    
    setIsLoading(true);
    try {
      const results = await suggestFeedsWithWorker(topic, []);
      setSuggestedFeeds(results);
    } catch (error) {
      console.error("Error suggesting feeds:", error);
    } finally {
      setIsLoading(false);
    }
  }, [topic]);

  // Handle subscribing to a suggested feed
  const handleSubscribeToFeed = useCallback((feed: FeedData) => {
    saveFeedToStorage({ title: feed.title, url: feed.url });
    setFeedUrlInput(""); // Clear input
    
    // Update saved feeds list
    const feeds = loadFeedsFromStorage();
    setSavedFeeds(feeds);
    
    // Remove the subscribed feed from suggestions
    setSuggestedFeeds(prev => prev.filter(f => f.url !== feed.url));
  }, []);

  // Handle removing a feed
  const handleRemoveFeed = useCallback((feedUrl: string) => {
    const feeds = loadFeedsFromStorage();
    const updatedFeeds = feeds.filter(feed => feed.url !== feedUrl);
    
    // Clear localStorage and add back the updated feeds
    localStorage.removeItem('rss_feeds');
    updatedFeeds.forEach(feed => saveFeedToStorage(feed));
    
    setSavedFeeds(updatedFeeds);
  }, []);

  return (
    <main className="space-y-8 pt-16 px-4">
      <h1 className="text-2xl font-semibold text-[var(--text-primary)]">Manage Feeds</h1>
      
      <section className="space-y-4">
        <h2 className="text-xl font-semibold text-[var(--text-primary)]">Add Feed</h2>
        <input
          type="file"
          accept=".opml, text/xml"
          onChange={async (e) => {
            const file = e.target.files?.[0];
            if (!file) return;
            setIsLoading(true);
            try {
              const text = await file.text();
              const parser = new DOMParser();
              const doc = parser.parseFromString(text, "text/xml");
              const outlines = doc.querySelectorAll("outline[type='rss']");
              outlines.forEach((el) => {
                const url = el.getAttribute("xmlUrl");
                const title = el.getAttribute("title") || el.getAttribute("text") || url;
                if (url) {
                  saveFeedToStorage({ title: title ?? url, url });
                }
              });
              
              // Update saved feeds list
              const feeds = loadFeedsFromStorage();
              setSavedFeeds(feeds);
            } catch (error) {
              console.error("Error importing OPML:", error);
            } finally {
              setIsLoading(false);
            }
          }}
          className="block mb-2 text-sm text-[var(--text-secondary)]"
        />
        <div className="flex flex-col sm:flex-row gap-3">
          <Input
            placeholder="Enter site URL or RSS feed"
            value={feedUrlInput}
            onChange={(e) => setFeedUrlInput(e.target.value)}
            className="flex-1"
          />
          <Button onClick={handleAddFeed} disabled={isLoading}>
            {isLoading ? <Spinner size="sm" /> : "Add Feed"}
          </Button>
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold text-[var(--text-primary)]">Suggest Feeds</h2>
        <div className="flex flex-col sm:flex-row gap-3">
          <Input
            placeholder="Enter a topic you're interested in"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            className="flex-1"
          />
          <Button onClick={handleTopicSuggest} disabled={isLoading}>
            {isLoading ? <Spinner size="sm" /> : "Suggest"}
          </Button>
        </div>
        <div className="grid gap-3">
          {suggestedFeeds.map((feed) => (
            <SuggestedFeed 
              key={feed.url} 
              feed={feed} 
              onSubscribe={handleSubscribeToFeed} 
            />
          ))}
        </div>
      </section>

      <section className="space-y-4">
        <h2 className="text-xl font-semibold text-[var(--text-primary)]">Your Feeds</h2>
        <div className="grid gap-3">
          {savedFeeds.length === 0 ? (
            <Card className="shadow-sm">
              <CardContent className="p-4 text-center">
                <p className="text-[var(--text-secondary)]">No feeds added yet. Add some feeds to get started.</p>
              </CardContent>
            </Card>
          ) : (
            savedFeeds.map((feed) => (
              <Card key={feed.url} className="shadow-sm">
                <CardContent className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <img
                        src={`https://www.google.com/s2/favicons?sz=32&domain_url=${feed.url}`}
                        className="w-6 h-6"
                        alt="favicon"
                      />
                      <div>
                        <p className="font-medium text-[var(--text-primary)]">{feed.title}</p>
                        <p className="text-xs text-[var(--text-secondary)]">{feed.url}</p>
                      </div>
                    </div>
                    <Button 
                      variant="destructive" 
                      className="text-sm py-1 px-3"
                      onClick={() => handleRemoveFeed(feed.url)}
                    >
                      Remove
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </section>
    </main>
  );
}